// Builds the generated runtime bundles (run: node tools/build-bundle.js; npm start / npm run dist run it automatically):
//   js/runtime-src.js      the runtime sources as strings, embedded by "Export → HTML page"
//   runtime/alike-web.js   one file for any web site: the JS runtime + the <alike-skeleton> web component
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const files = ['math', 'model', 'pose', 'animstate', 'render', 'atlas', 'binary'];
const src = {};
for (const f of files) src[f] = fs.readFileSync(path.join(root, 'js', f + '.js'), 'utf8');
src.element = fs.readFileSync(path.join(root, 'runtime', 'alike-element.js'), 'utf8');
const out = '/* generated by tools/build-bundle.js — do not edit */\nwindow.A = window.A || {};\nA.RUNTIME_SRC = ' + JSON.stringify(src) + ';\n';
fs.writeFileSync(path.join(root, 'js', 'runtime-src.js'), out);
const web = '/* Alike web runtime + <alike-skeleton> web component. Generated by tools/build-bundle.js — do not edit.\n   Usage: <script src="alike-web.js"></script> <alike-skeleton src="hero.json" animation="walk"></alike-skeleton> */\n' +
  'window.A = window.A || {};\n' + files.concat('element').map((f) => src[f]).join('\n');
fs.writeFileSync(path.join(root, 'runtime', 'alike-web.js'), web);
console.log('runtime-src.js:', Math.round(out.length / 1024) + ' KB · alike-web.js:', Math.round(web.length / 1024) + ' KB');
